import{_ as t,o as a,c as o,a2 as n}from"./chunks/framework.DGk0zlJw.js";const p=JSON.parse('{"title":"Phase 4 HTML Small Screen · Boundary Ruling and Architecture Decision (2026-10-17)","description":"","frontmatter":{},"headers":[],"relativePath":"design/phase4-html-ruling-2026-10-17.md","filePath":"design/phase4-html-ruling-2026-10-17.md"}'),i={name:"design/phase4-html-ruling-2026-10-17.md"};function r(d,e,s,l,c,h){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="phase-4-html-small-screen-·-boundary-ruling-and-architecture-decision-2026-10-17" tabindex="-1">Phase 4 HTML Small Screen · Boundary Ruling and Architecture Decision (2026-10-17) <a class="header-anchor" href="#phase-4-html-small-screen-·-boundary-ruling-and-architecture-decision-2026-10-17" aria-label="Permalink to &quot;Phase 4 HTML Small Screen · Boundary Ruling and Architecture Decision (2026-10-17)&quot;">​</a></h1><h2 id="_1-ruling-record" tabindex="-1">1. Ruling record <a class="header-anchor" href="#_1-ruling-record" aria-label="Permalink to &quot;1. Ruling record&quot;">​</a></h2><p>User ruling, 2026-10-17: &quot;Phase 4 HTML small screen (6 rows; an architecture decision must precede work; a counter-record exists in the repo) ... proceed with this design&quot;.</p><p>This document is the pre-work architecture decision deliverable. It answers the open question in <code>redesign-2026-10-16-契约.md</code> §4 (the HTML small screen vs. the <code>master-plan.md:769</code> &quot;no WebView&quot; boundary; mapping-and-migration §6.3). The open question is closed as of this file.</p><h2 id="_2-reconciliation-with-the-counter-record" tabindex="-1">2. Reconciliation with the counter-record <a class="header-anchor" href="#_2-reconciliation-with-the-counter-record" aria-label="Permalink to &quot;2. Reconciliation with the counter-record&quot;">​</a></h2><p>In-repo counter-record (<code>docs/master-plan.md:769</code>): &quot;floating windows should use native Windows capabilities as far as possible, without introducing WebView or any other UI framework to re-implement the desktop shell&quot;.</p><p>The design doc itself (<code>redesign-plan-2026-10-16.md</code>, last line of §7): &quot;Phase 1 may use controlled HTML/CSS templates; evaluate a restricted runtime only when JavaScript becomes necessary. React is not a required dependency.&quot;</p><p>The two do not conflict: the design&#39;s phase 1 does not require JavaScript, and Beacon&#39;s rendering segment is already a declarative component tree (Phase 3 <code>ComponentDescriptor</code> / <code>ComponentSurfaceRenderer</code>). Phase 1 is therefore ruled as —</p><blockquote><p><strong>Controlled HTML/CSS subset + native rendering. No JavaScript, no WebView2, no React.</strong> The HTML template is parsed inside Core into a <code>ComponentDescriptor</code> subtree and handed to the existing declarative renderer, which draws it with native WinUI controls. HTML is just &quot;another language for writing component trees&quot;, not another runtime.</p></blockquote><p>Faces that genuinely need JavaScript (arbitrary interaction logic, external scripts) are outside this ruling; a fresh ruling is required then.</p><h2 id="_3-carrier-and-expansion-point" tabindex="-1">3. Carrier and expansion point <a class="header-anchor" href="#_3-carrier-and-expansion-point" aria-label="Permalink to &quot;3. Carrier and expansion point&quot;">​</a></h2><ul><li>Carrier: the root node of any face key (tile / row / detail; the open face-key stance is unchanged) is declared as <code>{ &quot;type&quot;: &quot;htmltemplate&quot;, &quot;props&quot;: { &quot;html&quot;: &quot;&lt;template text&gt;&quot; } }</code>. Zero new model fields, zero new JSON top-level keys, zero new face keys — HTML is a node type, not a new storage shape.</li><li>Expansion point: inside the pure function <code>WidgetInstanceResolver.Resolve</code>, <code>HtmlTemplateParser</code> parses the template text into a component subtree (a wrapper column), which then passes the existing <code>ComponentTreeValidator</code> (8 depth / 32 children / 256 nodes — the blast-radius caps bind the synthesized tree too). After expansion all consumers of tile / row / detail gain HTML faces with zero changes.</li><li>The parser is a static pure function (upholding decision ⑩: no IO, no runtime services, no caching); parse failure returns null, and the caller falls back to traditional rendering — same stance as the existing &quot;invalid tree, whole tree dropped&quot;.</li></ul><h2 id="_4-template-format-closed-vocabulary" tabindex="-1">4. Template format (closed vocabulary) <a class="header-anchor" href="#_4-template-format-closed-vocabulary" aria-label="Permalink to &quot;4. Template format (closed vocabulary)&quot;">​</a></h2><p>Grammar skeleton: optional <code>&lt;style&gt;</code> blocks (must precede all other elements) plus an element tree. Double-quoted attributes; <code>&lt;!-- comments --&gt;</code> may be skipped over; <code>&amp;</code> entities and a bare <code>&amp;</code> are parse errors (a status-text vocabulary has no use for them; stay closed).</p><p>Element whitelist (mapped onto existing renderer registry type keys):</p><table tabindex="0"><thead><tr><th>Element</th><th>Mapped type key</th><th>Own attributes</th><th>Binding slot</th></tr></thead><tbody><tr><td>card</td><td>card</td><td>—</td><td>—</td></tr><tr><td>column / row</td><td>column / row</td><td>gap</td><td>—</td></tr><tr><td>text</td><td>text</td><td>size(body/caption)</td><td>text</td></tr><tr><td>section</td><td>sectionlabel</td><td>—</td><td>text</td></tr><tr><td>metric</td><td>metric</td><td>unit</td><td>value</td></tr><tr><td>progress</td><td>progress</td><td>width</td><td>progress</td></tr><tr><td>dot</td><td>statusdot</td><td>size</td><td>severity</td></tr><tr><td>badge</td><td>badge</td><td>—</td><td>text</td></tr><tr><td>kv</td><td>keyvalue</td><td>key</td><td>value</td></tr><tr><td>divider</td><td>divider (self-closing)</td><td>—</td><td>—</td></tr><tr><td>button</td><td>actionbutton</td><td>data-action (required)</td><td>text (button label)</td></tr></tbody></table><p>Attributes common to all elements: <code>class</code>, <code>when</code> (conditional display, passed through to ComponentVisibility). Unknown element, unknown attribute, an own attribute on the wrong element → parse error. The vocabulary is the whitelist: <code>&lt;script&gt;</code>, <code>&lt;iframe&gt;</code>, <code>&lt;img&gt;</code>, <code>&lt;a href&gt;</code>, <code>on*</code> event attributes and external protocols are <strong>inexpressible in the grammar</strong> — not &quot;filtering dangerous input&quot;, they simply do not exist in the vocabulary.</p><h2 id="_5-controlled-data-bridge" tabindex="-1">5. Controlled data bridge <a class="header-anchor" href="#_5-controlled-data-bridge" aria-label="Permalink to &quot;5. Controlled data bridge&quot;">​</a></h2><p>The <code>{{...}}</code> interpolation desugars into existing <code>ComponentBinding</code> (zero binding-engine changes):</p><ul><li><code>{{state.summary}}</code> → state source; the field name must be in the engine&#39;s closed field set (summary / severity / progress / detailUrl / lifecycle / connectionId / widgetId / widgetType);</li><li><code>{{payload.run_id}}</code> → state source in <code>payload:run_id</code> form (non-empty key, no second colon);</li><li><code>{{selector.value-hint}}</code> → selector source; the name must be in the selector registry (value-hint / quota-windows);</li><li>mixed interpolation in text content → split into a literal / bound child-node sequence; an attribute value that is exactly one interpolation → that attribute slot gets a binding, an attribute value mixing literal text with interpolation → parse error (error out, do not guess); <code>when</code> / <code>gap</code> / <code>class</code> / <code>size</code> / <code>unit</code> / <code>key</code> / <code>width</code> / <code>data-action</code> accept no interpolation (attributes are the configuration face; the data face is binding slots only).</li></ul><p>Unresolvable values become empty strings (the binding engine&#39;s existing fail-closed stance) — the process never crashes, no placeholder garbage is left.</p><h2 id="_6-action-id-bridge" tabindex="-1">6. Action ID bridge <a class="header-anchor" href="#_6-action-id-bridge" aria-label="Permalink to &quot;6. Action ID bridge&quot;">​</a></h2><p><code>&lt;button data-action=&quot;rerun-failed&quot;&gt;Retry failed&lt;/button&gt;</code> → an <code>actionbutton</code> node; the action ID accepts a <strong>static literal</strong> only (no interpolation, no whitespace) — design §7.3 &quot;never trust data passed in by the page&quot;: remote state data must not pick actions; the action face is declarable only by local configuration.</p><p>The execution side lives in the renderer (App; per decision ⑤ the type vocabulary belongs to the renderer): the ID is looked up in the actions.json + connection DSL action universe, filtered by <code>ActionVisibility</code> (widgetType / connection_id constraints apply as usual); nonexistent or invisible → a diagnostic placeholder is rendered (no clickable button); present and visible → executed through the existing <code>ActionRunner.ExecuteAsync</code> path, <code>RequireConfirmation</code> honored as usual. A template declaring a nonexistent action ID does not crash the process — the face renders as usual, the button slot shows diagnostic text.</p><h2 id="_7-theme-tokens-and-basic-style-adaptation" tabindex="-1">7. Theme tokens and basic style adaptation <a class="header-anchor" href="#_7-theme-tokens-and-basic-style-adaptation" aria-label="Permalink to &quot;7. Theme tokens and basic style adaptation&quot;">​</a></h2><p>A <code>&lt;style&gt;</code> block accepts only the <code>.class { prop: value; }</code> form (one class per rule, no combinators, no pseudo-classes):</p><ul><li>prop whitelist: <code>tone</code> (info / ok / warn / bad), <code>pad</code> (sm / md / lg), <code>gap</code> (sm / md / lg);</li><li>values accept token words only; <code>#hex</code>, <code>rgb()</code>, named CSS colors — literal colors are parse errors — <strong>a template cannot hardcode colors in the grammar</strong>, and light / dark / high-contrast adapt automatically (rendering goes through ThemeColors / UiPalette severity colors);</li><li>the DIP conversion of sm / md / lg happens renderer-side (sm=4 / md=8 / lg=12, aligned with DesignTokens Space4/8/12); Core stores only token words — type conversion stays at render time (the established all-string Props stance);</li><li>duplicate class definition, unknown prop, unknown token word → parse error.</li></ul><h2 id="_8-incremental-update-semantics" tabindex="-1">8. Incremental update semantics <a class="header-anchor" href="#_8-incremental-update-semantics" aria-label="Permalink to &quot;8. Incremental update semantics&quot;">​</a></h2><ul><li>Template parses once per configuration revision: the instance is immutable and resolved with the configuration (the established &quot;re-layout only re-resolves&quot; invariant), and the template text re-parses only when the configuration changes;</li><li>data arrival = existing binding re-evaluation + face re-render (the Phase 3 whole-tree re-render stance, trees ≤256 nodes); <strong>&quot;regenerating the whole HTML on every data change&quot; is not the mechanism</strong> (design §7.2) — the HTML text never participates in the data update path at all; updates go through structured bindings (the engine evaluates the same synthesized tree against the new state snapshot);</li><li>Core-testable fact: the same instance with two state snapshots → different binding values, unchanged synthesized tree object.</li></ul><h2 id="_9-instance-lifecycle-and-error-fallback" tabindex="-1">9. Instance lifecycle and error fallback <a class="header-anchor" href="#_9-instance-lifecycle-and-error-fallback" aria-label="Permalink to &quot;9. Instance lifecycle and error fallback&quot;">​</a></h2><ul><li>Instance lifecycle = the existing WidgetInstance lifecycle: resolved on configuration load / change, shared read-only, no separate runtime state, no timers, no background tasks (the HTML face introduces no new lifecycle shape);</li><li>error fallback: parse failure / out-of-vocabulary → the face is dropped, traditional rendering resumes, with diagnostics (load side into LoadErrors, resolve side fail-closed null) — a broken template must not crash the resident process, nor be silently trimmed into half a tree;</li><li>the storage layer&#39;s <code>SanitizeWidgetComponents</code> expands and validates at load: a bad template is reported and dropped at load time, not discovered at first render.</li></ul><h2 id="_10-explicitly-out-of-scope" tabindex="-1">10. Explicitly out of scope <a class="header-anchor" href="#_10-explicitly-out-of-scope" aria-label="Permalink to &quot;10. Explicitly out of scope&quot;">​</a></h2><ul><li>JavaScript / restricted script runtimes / WebView2 / React — a fresh user ruling is required when needed;</li><li>arbitrary CSS styling (layout models, fonts, motion, images) — extending the vocabulary whitelist is later evolution, reviewed item by item;</li><li>styles shared across templates, external template files, template hot-reload — templates travel only with widgets.json;</li><li>cross-widget data reads (additional-source declarations follow the existing Phase 3 stance; whitelist validation is unchanged).</li></ul>',33)])])}const m=t(i,[["render",r]]);export{p as __pageData,m as default};
